/* ==========================================================================
   Module 5 — People, Appointments & Competency
   ========================================================================== */
'use strict';

function personTrainingPct(p) { const req = requiredCourses(p); if (!req.length) return null; return pct(req.filter(c => ['Valid', 'Expiring'].includes(trainingStatus(p.id, c).status)).length, req.length); }
ROUTES.people = (p, q) => {
  if (p[0] && /^P-\d+/.test(p[0])) return personDetail(p[0]);
  const tab = p[0] || 'register';
  const people = peopleInScope();
  const appts = scoped('appointments');
  const apIssues = appts.filter(a => apptStatus(a) !== 'Valid').length;
  let gaps = 0; people.forEach(x => requiredCourses(x).forEach(c => { if (['Missing', 'Expired'].includes(trainingStatus(x.id, c).status)) gaps++; }));
  const toVerify = S.training.filter(t => inScope(person(t.person)) && !t.competency && ['Operational Competency'].includes(byId('courses', t.course).category)).length;
  const tabs = [['register', 'Employee & contractor register', people.length], ['appointments', 'Legal appointments', apIssues || '', apIssues ? 'red' : ''], ['training', 'Training records'], ['matrix', 'Training matrix', gaps || '', gaps ? 'red' : ''], ['competency', 'Competency verification', toVerify || ''], ['medical', 'Medical fitness (restricted)']];
  let body = '', actions = '';
  if (tab === 'register') {
    actions = permBtn('admin', `<button class="btn primary" data-act="personNew">${icon('plus', 'sm')} Add person</button>`);
    body = listView('people', { rows: people, placeholder: 'Search name, job title…', search: x => [x.name, x.jobTitle, x.dept, x.company || ''].join(' '), href: x => '#/people/' + x.id,
      filters: [{ id: 'type', label: 'All types', options: ['Employee', 'Contractor', 'Consultant'], test: (x, v) => x.type === v }, { id: 'site', label: 'All sites', options: orgSites().map(s => ({ value: s.id, label: s.short })), test: (x, v) => x.site === v }, { id: 'dept', label: 'All departments', options: S.departments, test: (x, v) => x.dept === v }],
      columns: [
        { label: 'Name', render: x => `<div class="t-title">${esc(x.name)}</div><div class="t-sub">${esc(x.id)} · ${esc(x.email)}</div>` },
        { label: 'Role / job title', render: x => esc(x.jobTitle) + (x.company ? `<div class="t-sub">${esc(x.company)}</div>` : '') },
        { label: 'Type', render: x => badge(x.type, x.type === 'Employee' ? 'navy' : 'orange', true) },
        { label: 'Site / department', render: x => `${esc(sname(x.site))}<div class="t-sub">${esc(x.dept)}</div>` },
        { label: 'Training', render: x => { const v = personTrainingPct(x); return v == null ? '<span class="muted">No role requirements</span>' : `<span class="due ${scoreColour(v)}">${v}% current</span>`; } },
        { label: 'Appointments', render: x => { const a = S.appointments.filter(y => y.person === x.id); return a.length ? a.map(y => badge(y.type, STATUS_COLOURS[apptStatus(y)], true)).join(' ') : '<span class="muted">—</span>'; } }
      ] });
  }
  if (tab === 'appointments') {
    actions = permBtn('legal.assess', `<button class="btn primary" data-act="apptNew">${icon('plus', 'sm')} New appointment</button>`);
    body = listView('appts', { rows: appts, initial: { status: q.status || '' }, placeholder: 'Search person, appointment…', search: a => [a.id, pname(a.person), a.type, a.legalRef].join(' '),
      rowClass: a => apptStatus(a) === 'Expired' ? 'row-red' : apptStatus(a) !== 'Valid' ? 'row-amber' : '',
      filters: [{ id: 'status', label: 'All statuses', options: ['Valid', 'Expiring', 'Expired', 'Not accepted', 'Vacant'], test: (a, v) => apptStatus(a) === v }, { id: 'type', label: 'All types', options: uniq(appts.map(a => a.type)), test: (a, v) => a.type === v }],
      columns: [
        { label: 'Appointment', render: a => `<div class="t-title">${esc(a.type)}</div><div class="t-sub">${esc(a.legalRef)} <span class="demo-tag">verify</span></div>` },
        { label: 'Appointee', render: a => a.person ? `<a href="#/people/${a.person}">${esc(pname(a.person))}</a>` : `<span class="due red">Vacant</span>${a.fromLegal ? `<div class="t-sub">Required by <a href="#/legal/${a.fromLegal}">${a.fromLegal}</a></div>` : ''}` },
        { label: 'Site', render: a => esc(sname(a.site)) },
        { label: 'Appointed by / date', render: a => `${esc(pname(a.appointedBy))}<div class="t-sub">${fmt(a.date)}</div>` },
        { label: 'Expiry', render: a => dueText(a.expiry) },
        { label: 'Letter & acceptance', render: a => `${a.letter ? fileChip(a.letter) : '<span class="badge b-red">No letter</span>'}<div class="t-sub">${a.accepted ? 'Accepted ' + fmt(a.acceptedOn) : '<b style="color:var(--amber)">Acceptance outstanding</b>'}</div>` },
        { label: 'Status', render: a => sbadge(apptStatus(a)) },
        { label: '', render: a => !a.person ? permBtn('legal.assess', `<button class="btn sm primary" data-act="apptFill" data-id="${a.id}">Appoint person</button>`) : `<div class="btn-row">${!a.accepted ? `<button class="btn sm" data-act="apptAccept" data-id="${a.id}">Record acceptance</button>` : ''}${apptStatus(a) !== 'Valid' ? permBtn('legal.assess', `<button class="btn sm primary" data-act="apptRenew" data-id="${a.id}">Renew</button>`) : ''}</div>` }
      ] });
    if (q.id) setTimeout(() => { const st = LV.state.appts; st.q = q.id; const i = document.querySelector('[data-lv=appts][data-lvf=__q]'); if (i) i.value = q.id; refreshList('appts'); }, 0);
  }
  if (tab === 'training') {
    actions = `<button class="btn primary" data-act="trainNew">${icon('plus', 'sm')} Record training</button>`;
    const recs = S.training.filter(t => inScope(person(t.person)));
    body = `<div class="card mb"><div class="card-head"><h2>Courses, categories and validity</h2><span class="ch-sub">Training providers are fictional</span></div><div class="card-body flush"><table class="tbl compact stackable"><thead><tr><th>Course</th><th>Category</th><th>Validity</th><th>Provider</th><th>Required for roles</th><th>Material</th></tr></thead><tbody>${S.courses.map(c => `<tr ${q.course === c.id ? 'style="background:var(--blue-50)"' : ''}><td data-label="Course"><b>${esc(c.name)}</b></td><td data-label="Category">${esc(c.category)}</td><td data-label="Validity">${c.months ? c.months + ' months' : 'No expiry'}</td><td data-label="Provider">${esc(c.provider)}</td><td data-label="Roles">${Object.keys(S.roleReqs).filter(r => S.roleReqs[r].includes(c.id)).map(r => `<span class="tag">${esc(r)}</span>`).join(' ')}</td><td data-label="Material">${c.doc ? `<a href="#/documents/${c.doc}">${esc(byId('documents', c.doc).number)}</a>` : '—'}</td></tr>`).join('')}</tbody></table></div></div>` +
      listView('trn', { rows: recs, placeholder: 'Search person or course…', search: t => pname(t.person) + ' ' + byId('courses', t.course).name, filters: [{ id: 'status', label: 'All statuses', options: ['Valid', 'Expiring', 'Expired'], test: (t, v) => validity(t.expiry, S.config.notify.trainingLead) === v }, { id: 'course', label: 'All courses', options: S.courses.map(c => ({ value: c.id, label: c.name })), test: (t, v) => t.course === v }],
        columns: [{ label: 'Person', render: t => `<a href="#/people/${t.person}">${esc(pname(t.person))}</a>` }, { label: 'Course', render: t => esc(byId('courses', t.course).name) }, { label: 'Attended', render: t => fmt(t.date) }, { label: 'Expiry', render: t => t.expiry ? dueText(t.expiry) : 'No expiry' }, { label: 'Provider', render: t => esc(t.provider) }, { label: 'Certificate', render: t => fileChip(t.certificate) }, { label: 'Competency', render: t => t.competency ? `<span class="badge b-green">Verified</span><div class="t-sub">${esc(pname(t.competency.by))}</div>` : '<span class="badge b-grey">Not verified</span>' }] });
  }
  if (tab === 'matrix') {
    const rows = people.filter(x => requiredCourses(x).length);
    const cs = S.courses.filter(c => rows.some(x => requiredCourses(x).includes(c.id)));
    body = `<div class="alert info">${icon('info')}<div>Required courses come from the job-title requirements (Administration → Training categories). Click any red or amber cell to record training or raise a training-gap action.</div></div>
    <div class="card"><div class="card-body flush"><div class="table-wrap"><table class="tbl tm-table compact"><thead><tr><th>Person</th>${cs.map(c => `<th title="${esc(c.name)}">${esc(c.name.split(' ').slice(0, 3).join(' '))}</th>`).join('')}<th>Current</th></tr></thead><tbody>
      ${rows.map(x => `<tr><td><a href="#/people/${x.id}"><b>${esc(x.name)}</b></a><div class="t-sub">${esc(x.jobTitle)} · ${esc(sname(x.site))}</div></td>${cs.map(c => { if (!requiredCourses(x).includes(c.id)) return '<td><span class="tm-cell tm-na">n/a</span></td>'; const t = trainingStatus(x.id, c.id); const cls = t.status === 'Valid' ? 'tm-ok' : t.status === 'Expiring' ? 'tm-exp' : 'tm-bad'; return `<td><button class="tm-cell ${cls}" data-act="matrixCell" data-p="${x.id}" data-c="${c.id}" title="${esc(c.name)}: ${t.status}${t.rec && t.rec.expiry ? ' — expires ' + fmt(t.rec.expiry) : ''}">${t.status}${t.rec && t.rec.expiry ? `<br><small>${fmt(t.rec.expiry)}</small>` : ''}</button></td>`; }).join('')}<td><span class="due ${scoreColour(personTrainingPct(x))}">${personTrainingPct(x)}%</span></td></tr>`).join('')}
    </tbody></table></div></div></div>`;
  }
  if (tab === 'competency') {
    const recs = S.training.filter(t => inScope(person(t.person)) && byId('courses', t.course).category === 'Operational Competency');
    body = `<div class="alert info">${icon('info')}<div>Attendance alone does not prove competence. Operational courses require a supervisor or assessor to verify competence (practical assessment / observation) before the person is authorised.</div></div>` + listView('comp', { rows: recs, search: t => pname(t.person) + ' ' + byId('courses', t.course).name, filters: [{ id: 'v', label: 'All', options: [{ value: 'no', label: 'Not yet verified' }, { value: 'yes', label: 'Verified' }], test: (t, v) => v === 'no' ? !t.competency : !!t.competency }], initial: { v: 'no' },
      columns: [{ label: 'Person', render: t => `<a href="#/people/${t.person}">${esc(pname(t.person))}</a><div class="t-sub">${esc(person(t.person).jobTitle)}</div>` }, { label: 'Course', render: t => esc(byId('courses', t.course).name) }, { label: 'Training date', render: t => fmt(t.date) }, { label: 'Status', render: t => t.competency ? `<span class="badge b-green">Verified ${fmt(t.competency.date)}</span><div class="t-sub">${esc(pname(t.competency.by))} · ${esc(t.competency.method)}</div>` : '<span class="badge b-amber">Verification outstanding</span>' }, { label: '', render: t => t.competency ? '' : permBtn('inspect', `<button class="btn sm primary" data-act="compVerify" data-id="${t.id}">Verify competency</button>`) }] });
  }
  if (tab === 'medical') {
    body = can('medical.view')
      ? `<div class="alert warn">${icon('lock')}<div><b>Restricted health information.</b> Visible only to authorised roles (HSEQ Manager / occupational health). Only fitness outcomes and restrictions are shown — clinical details stay with the occupational health practitioner. <b>Prototype note:</b> this restriction is applied in the browser for demonstration only; production must enforce it on the server (row-level security, audit logging, POPIA-aligned handling).</div></div>
        <div class="card"><div class="card-body flush"><table class="tbl stackable"><thead><tr><th>Person</th><th>Assessment</th><th>Date</th><th>Outcome</th><th>Restrictions</th><th>Next due</th></tr></thead><tbody>${S.medical.filter(m => inScope(person(m.person))).map(m => `<tr><td data-label="Person"><a href="#/people/${m.person}">${esc(pname(m.person))}</a></td><td data-label="Assessment">${esc(m.type)}</td><td data-label="Date">${fmt(m.date)}</td><td data-label="Outcome">${badge(m.result, m.result === 'Fit' ? 'green' : 'amber')}</td><td data-label="Restrictions">${esc(m.restrictions || '—')}</td><td data-label="Next due">${dueText(m.next)}</td></tr>`).join('')}</tbody></table></div></div>`
      : restrictedPanel();
  }
  const html = `${pageHead('People, appointments & competency', 'Employees, contractors and consultants; legal appointments with letters and acceptance; training requirements by role, records, expiry and competency verification.', actions, scopePill())}
    <div class="kpis">
      ${kpi('People in scope', people.length, `${people.filter(x => x.type === 'Contractor').length} contractors · ${people.filter(x => x.type === 'Consultant').length} consultants`, 'blue', '#/people/register', 'people')}
      ${kpi('Appointment issues', apIssues, 'Expired, expiring or not accepted', apIssues ? 'amber' : 'green', '#/people/appointments', 'file')}
      ${kpi('Training gaps', gaps, 'Required training missing or expired', gaps ? 'red' : 'green', '#/people/matrix', 'alert')}
      ${kpi('Competency to verify', toVerify, 'Operational training not yet verified', toVerify ? 'amber' : 'green', '#/people/competency', 'checkCircle')}
    </div>
    ${tabsHtml('#/people', tabs, tab)}${body}`;
  return { title: 'People & competency', nav: 'people', crumbs: [['People & competency', '#/people'], [tabs.find(t => t[0] === tab)[1], '#']], html };
};
function restrictedPanel() { return `<div class="card"><div class="empty">${icon('lock')}<h2>Restricted information</h2><p>Medical fitness records are only visible to authorised roles (e.g. HSEQ Manager / occupational health practitioner).<br>Your demo role: <b>${esc(myRole().name)}</b>.</p><p class="muted">Prototype: switch user via the user menu to see the authorised view. Production enforces this on the server.</p></div></div>`; }

function personDetail(id) {
  const p = person(id); if (!p) return ROUTES.notfound();
  const req = requiredCourses(p);
  const appts = S.appointments.filter(a => a.person === id);
  const ppe = S.ppeIssues.filter(x => x.person === id);
  const incs = S.incidents.filter(i => i.persons.includes(id) || i.reporter === id);
  const acts = S.actions.filter(a => a.owner === id);
  const med = S.medical.filter(m => m.person === id);
  const html = `<div class="status-hero"><div class="avatar" style="width:48px;height:48px;font-size:16px">${initials(p.name)}</div><div><div class="sh-id">${p.id} · ${esc(p.type)}</div><h1 style="margin:2px 0 4px">${esc(p.name)}</h1><div class="btn-row"><span class="tag">${esc(p.jobTitle)}</span><span class="tag">${esc(sname(p.site))}</span><span class="tag">${esc(p.dept)}</span>${p.sysRole ? badge('System role: ' + p.sysRole, 'navy', true) : ''}</div></div>
    <div class="sh-actions"><button class="btn" data-act="trainNew" data-p="${p.id}">${icon('plus', 'sm')} Record training</button>${permBtn('action.create', `<button class="btn" data-act="trainGap" data-p="${p.id}">Raise training-gap action</button>`)}</div></div>
  <div class="detail"><div class="stack">
    <div class="card"><div class="card-head"><h2>Required training for “${esc(p.jobTitle)}”</h2></div><div class="card-body flush">${req.length ? `<table class="tbl stackable"><thead><tr><th>Course</th><th>Status</th><th>Last attended</th><th>Expiry</th><th>Certificate</th><th>Competency</th></tr></thead><tbody>${req.map(c => { const t = trainingStatus(id, c), crs = byId('courses', c); return `<tr><td data-label="Course"><b>${esc(crs.name)}</b><div class="t-sub">${esc(crs.category)}</div></td><td data-label="Status">${sbadge(t.status)}</td><td data-label="Attended">${t.rec ? fmt(t.rec.date) : '—'}</td><td data-label="Expiry">${t.rec ? (t.rec.expiry ? dueText(t.rec.expiry) : 'No expiry') : '—'}</td><td data-label="Certificate">${t.rec ? fileChip(t.rec.certificate) : '—'}</td><td data-label="Competency">${t.rec && t.rec.competency ? badge('Verified', 'green') : t.rec ? badge('Not verified', 'grey') : '—'}</td></tr>`; }).join('')}</tbody></table>` : '<div class="empty">No role-based training requirements configured.</div>'}</div></div>
    <div class="card"><div class="card-head"><h2>Legal appointments</h2></div><div class="card-body">${appts.length ? `<ul class="link-list">${appts.map(a => `<li><div class="ll-main"><b>${esc(a.type)}</b><div>${esc(a.legalRef)} · ${esc(sname(a.site))} · expires ${fmt(a.expiry)} · ${a.accepted ? 'accepted' : 'acceptance outstanding'}</div></div>${sbadge(apptStatus(a))}</li>`).join('')}</ul>` : '<p class="muted">None.</p>'}</div></div>
    <div class="card"><div class="card-head"><h2>PPE issued</h2></div><div class="card-body">${ppe.length ? `<ul class="link-list">${ppe.map(x => `<li><div class="ll-main"><b>${esc(byId('ppeTypes', x.ppe).name)}</b><div>Issued ${fmt(x.issued)} · size ${esc(x.size)}</div></div>${dueText(x.replaceBy)}</li>`).join('')}</ul>` : '<p class="muted">No PPE issue records.</p>'}</div></div>
  </div><div class="stack">
    <div class="card"><div class="card-head"><h2>Details</h2></div><div class="card-body"><div class="kv"><div>Email</div><div>${esc(p.email)}</div><div>Organisation</div><div>${esc(orgOf(p.org).short)}</div><div>Branch</div><div>${esc(site(p.site).name)}</div><div>Start date</div><div>${fmt(p.started)}</div>${p.company ? `<div>Company</div><div>${esc(p.company)}</div>` : ''}<div>Status</div><div>${badge(p.status, 'green')}</div></div></div></div>
    <div class="card"><div class="card-head"><h2>Actions owned</h2></div><div class="card-body">${acts.length ? `<ul class="link-list">${acts.map(a => `<li><div class="ll-main"><a href="#/actions/${a.id}">${a.id}</a><div>${esc(a.title)}</div></div>${sbadge(a.status)}</li>`).join('')}</ul>` : '<p class="muted">None.</p>'}</div></div>
    <div class="card"><div class="card-head"><h2>Incidents</h2></div><div class="card-body">${incs.length ? `<ul class="link-list">${incs.map(i => `<li><div class="ll-main"><a href="#/incidents/${i.id}">${i.id}</a><div>${esc(i.title)}</div></div>${sbadge(i.status)}</li>`).join('')}</ul>` : '<p class="muted">None.</p>'}</div></div>
    <div class="card"><div class="card-head"><h2>${icon('lock', 'sm')} Medical fitness</h2></div><div class="card-body">${can('medical.view') ? (med.length ? med.map(m => `<div>${badge(m.result, m.result === 'Fit' ? 'green' : 'amber')} ${esc(m.type)} · next ${dueText(m.next)}${m.restrictions ? `<div class="t-sub">${esc(m.restrictions)}</div>` : ''}</div>`).join('') : '<p class="muted">No records.</p>') : `<p class="muted">${icon('lock', 'sm')} Restricted — not visible to ${esc(myRole().name)}.</p>`}</div></div>
  </div></div>`;
  return { title: p.name, nav: 'people', crumbs: [['People & competency', '#/people'], [p.name, '#']], html };
}

ACT.matrixCell = (el) => {
  const p = person(el.dataset.p), c = byId('courses', el.dataset.c), t = trainingStatus(p.id, c.id);
  openModal({ title: c.name, sub: `${esc(p.name)} — ${esc(p.jobTitle)}`, size: 'narrow', body: `<p>Status: ${sbadge(t.status)}</p>${t.rec ? `<p>Last attended ${fmt(t.rec.date)}${t.rec.expiry ? ', expires ' + fmt(t.rec.expiry) : ''}.</p>` : '<p>No training record on file.</p>'}`,
    buttons: [{ label: 'Raise training-gap action', onClick: () => { setTimeout(() => raiseActionModal({ source: 'Training', sourceId: p.id, title: `Training ${t.status.toLowerCase()}: ${c.name} — ${p.name}`, action: `Book ${p.name} on ${c.name} (${c.provider}) and file certificate.`, site: p.site, owner: site(p.site).manager, priority: t.status === 'Expired' || t.status === 'Missing' ? 'High' : 'Medium' }), 30); } }, { label: 'Record training', cls: 'primary', onClick: () => { setTimeout(() => ACT.trainNew({ dataset: { p: p.id, c: c.id } }), 30); } }] });
};
ACT.trainNew = (el) => {
  const pre = el && el.dataset ? el.dataset : {};
  openModal({ title: 'Record training attendance', size: 'wide', body: `<div class="form-grid">${fld({ name: 'person', label: 'Person', type: 'select', options: personOptions(pre.p), required: true })}${fld({ name: 'course', label: 'Course', type: 'select', options: opts(S.courses.map(c => ({ value: c.id, label: c.name })), pre.c || '', '— Select —'), required: true })}${fld({ name: 'date', label: 'Date attended', type: 'date', value: TODAY, required: true })}${fld({ name: 'provider', label: 'Training provider', value: '' })}${fld({ name: 'certificate', label: 'Certificate / attendance proof', type: 'file', required: true, full: true })}${fld({ name: 'verified', label: 'Competency verified by me (practical assessment / observation)', type: 'checkbox', full: true })}</div><p class="muted mt-s">Expiry is calculated from the course validity period.</p>`,
    onOpen: m => { const s = m.querySelector('[name=course]'); const up = () => { const c = byId('courses', s.value); if (c) m.querySelector('[name=provider]').value = c.provider; }; s.addEventListener('change', up); up(); },
    buttons: [{ label: 'Save training record', cls: 'primary', onClick: m => {
      if (!validateForm(m, fail => { const d = m.querySelector('[name=date]'); if (d.value > TODAY) fail(d, 'Attendance date cannot be in the future.'); })) return false;
      const v = readForm(m), c = byId('courses', v.course), id = nextId('TR-', 'training');
      S.training.push({ id, person: v.person, course: v.course, date: v.date, expiry: c.months ? addMonths(v.date, c.months) : null, provider: v.provider, certificate: v.certificate, competency: v.verified ? { by: S.ui.user, date: TODAY, method: 'Practical assessment / observation' } : null });
      log(`Recorded ${c.name} for ${pname(v.person)}`, '#/people/' + v.person); save(); toast(`Training recorded. ${c.months ? 'Valid until ' + fmt(addMonths(v.date, c.months)) + '.' : ''}`); rerender();
    } }] });
};
ACT.trainGap = (el) => { const p = person(el.dataset.p); const gaps = requiredCourses(p).filter(c => ['Missing', 'Expired', 'Expiring'].includes(trainingStatus(p.id, c).status)).map(c => byId('courses', c).name); raiseActionModal({ source: 'Training', sourceId: p.id, title: `Training gap — ${p.name}`, action: gaps.length ? 'Arrange: ' + gaps.join(', ') : '', site: p.site, owner: site(p.site).manager }); };
ACT.compVerify = (el) => { const t = byId('training', el.dataset.id); openModal({ title: 'Verify competency', sub: `${esc(pname(t.person))} — ${esc(byId('courses', t.course).name)}`, body: `<div class="form-grid">${fld({ name: 'method', label: 'Verification method', type: 'select', options: opts(['Practical assessment / observation', 'Written assessment', 'Assessor sign-off (external)']), required: true })}${fld({ name: 'note', label: 'Observations', type: 'textarea', required: true, full: true })}${fld({ name: 'file', label: 'Assessment record (optional)', type: 'file', full: true })}</div>`, buttons: [{ label: 'Confirm competent', cls: 'success', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); t.competency = { by: S.ui.user, date: TODAY, method: v.method, note: v.note }; log(`Verified competency of ${pname(t.person)} (${byId('courses', t.course).name})`, '#/people/' + t.person); save(); toast('Competency verified.'); rerender(); } }] }); };
function apptForm(a) { return `<div class="form-grid">${fld({ name: 'person', label: 'Appointee', type: 'select', options: personOptions(a ? a.person : ''), required: true })}${fld({ name: 'type', label: 'Appointment type', type: 'select', options: opts(uniq(S.appointments.map(x => x.type)), a ? a.type : ''), required: true })}${fld({ name: 'legalRef', label: 'Legal reference', value: a ? a.legalRef : '', required: true, hint: 'Illustrative — verify the applicable section / regulation.' })}${fld({ name: 'site', label: 'Site', type: 'select', options: siteOptions(a ? a.site : defaultSite()), required: true })}${fld({ name: 'appointedBy', label: 'Appointed by', type: 'select', options: personOptions(a ? a.appointedBy : S.ui.user), required: true })}${fld({ name: 'date', label: 'Appointment date', type: 'date', value: TODAY, required: true })}${fld({ name: 'expiry', label: 'Valid until', type: 'date', value: addMonths(TODAY, 24), required: true })}${fld({ name: 'letter', label: 'Signed appointment letter', type: 'file', full: true })}${fld({ name: 'accepted', label: 'Appointee has signed acceptance', type: 'checkbox', full: true })}</div>`; }
ACT.apptNew = () => openModal({ title: 'New legal appointment', size: 'wide', body: apptForm(null), buttons: [{ label: 'Save appointment', cls: 'primary', onClick: m => { if (!validateForm(m, fail => { const e = m.querySelector('[name=expiry]'); if (e.value <= m.querySelector('[name=date]').value) fail(e, 'Expiry must be after the appointment date.'); })) return false; const v = readForm(m); const id = nextId('APP-', 'appointments'); S.appointments.push({ id, person: v.person, type: v.type, legalRef: v.legalRef, site: v.site, appointedBy: v.appointedBy, date: v.date, expiry: v.expiry, accepted: v.accepted, acceptedOn: v.accepted ? TODAY : null, letter: v.letter }); log(`Appointed ${pname(v.person)} as ${v.type}`, '#/people/appointments'); save(); toast('Appointment recorded.'); rerender(); } }] });
ACT.apptAccept = (el) => { const a = byId('appointments', el.dataset.id); openModal({ title: 'Record acceptance', sub: `${esc(pname(a.person))} — ${esc(a.type)}`, body: fld({ name: 'file', label: 'Signed acceptance', type: 'file', required: true }), buttons: [{ label: 'Record acceptance', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; a.accepted = true; a.acceptedOn = TODAY; a.letter = readForm(m).file; log(`${pname(a.person)} accepted appointment ${a.type}`, '#/people/appointments'); save(); toast('Acceptance recorded.'); rerender(); } }] }); };
ACT.apptRenew = (el) => { const a = byId('appointments', el.dataset.id); openModal({ title: 'Renew appointment', sub: `${esc(pname(a.person))} — ${esc(a.type)}`, body: `<div class="form-grid">${fld({ name: 'expiry', label: 'New expiry date', type: 'date', value: addMonths(TODAY, 24), required: true })}${fld({ name: 'letter', label: 'New signed appointment letter', type: 'file', required: true })}${fld({ name: 'accepted', label: 'Acceptance signed', type: 'checkbox', value: true, full: true })}</div>`, buttons: [{ label: 'Renew', cls: 'primary', onClick: m => { if (!validateForm(m)) return false; const v = readForm(m); a.date = TODAY; a.expiry = v.expiry; a.letter = v.letter; a.accepted = v.accepted; a.acceptedOn = v.accepted ? TODAY : null; log(`Renewed appointment ${a.id}`, '#/people/appointments'); save(); toast(`Renewed until ${fmt(v.expiry)}.`); rerender(); } }] }); };
ACT.personNew = () => openModal({ title: 'Add person', size: 'wide', body: `<div class="form-grid">${fld({ name: 'name', label: 'Full name', required: true })}${fld({ name: 'jobTitle', label: 'Job title', type: 'select', options: opts(Object.keys(S.roleReqs).concat(['Electrical Contractor', 'Other']), ''), required: true, hint: 'Training requirements follow the job title.' })}${fld({ name: 'type', label: 'Type', type: 'select', options: opts(['Employee', 'Contractor', 'Consultant']), required: true })}${fld({ name: 'site', label: 'Branch', type: 'select', options: siteOptions(defaultSite(), false), required: true })}${fld({ name: 'dept', label: 'Department', type: 'select', options: opts(S.departments), required: true })}${fld({ name: 'email', label: 'Email', type: 'email', required: true })}${fld({ name: 'company', label: 'Company (contractors)' })}</div>`,
  buttons: [{ label: 'Add person', cls: 'primary', onClick: m => { if (!validateForm(m, fail => { const e = m.querySelector('[name=email]'); if (e.value && !/^\S+@\S+\.\S+$/.test(e.value)) fail(e, 'Enter a valid email address.'); })) return false; const v = readForm(m); const id = nextId('P-', 'people'); S.people.push({ id, name: v.name, jobTitle: v.jobTitle, site: v.site, org: siteOrgOf(v.site), dept: v.dept, type: v.type, sysRole: null, email: v.email, company: v.company, status: 'Active', started: TODAY }); log(`Added ${v.name} to people register`, '#/people/' + id); save(); toast(`${esc(v.name)} added. Required training: ${(S.roleReqs[v.jobTitle] || []).length} course(s).`); navigate('#/people/' + id); } }] });
ACT.apptFill = (el) => { const a = byId('appointments', el.dataset.id); openModal({ title: 'Appoint person', sub: `${esc(a.type)} — ${esc(sname(a.site))}`, size: 'wide', body: `<div class="form-grid">${fld({ name: 'person', label: 'Appointee', type: 'select', options: personOptions('', p => p.site === a.site || a.site === 'ALL'), required: true })}${fld({ name: 'appointedBy', label: 'Appointed by', type: 'select', options: personOptions(a.appointedBy || S.ui.user), required: true })}${fld({ name: 'date', label: 'Appointment date', type: 'date', value: TODAY, required: true })}${fld({ name: 'expiry', label: 'Valid until', type: 'date', value: addMonths(TODAY, 24), required: true })}${fld({ name: 'letter', label: 'Signed appointment letter', type: 'file', required: true, full: true })}${fld({ name: 'accepted', label: 'Appointee has signed acceptance', type: 'checkbox', full: true })}</div>`,
  buttons: [{ label: 'Appoint', cls: 'primary', onClick: m => { if (!validateForm(m, fail => { const e = m.querySelector('[name=expiry]'); if (e.value <= m.querySelector('[name=date]').value) fail(e, 'Expiry must be after the appointment date.'); })) return false; const v = readForm(m); Object.assign(a, { person: v.person, appointedBy: v.appointedBy, date: v.date, expiry: v.expiry, letter: v.letter, accepted: v.accepted, acceptedOn: v.accepted ? TODAY : null }); log(`Appointed ${pname(v.person)} as ${a.type}${a.fromLegal ? ' (required by ' + a.fromLegal + ')' : ''}`, '#/people/appointments'); save(); toast(`${esc(pname(v.person))} appointed as ${esc(a.type)}.`); rerender(); } }] }); };
